  insert into public.missions (slug, mission_no, emoji, title, description, category_id, difficulty, status, stages, reward_rules, engine_options, objectives, access, level_id, risk_level, family)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"🍅","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"Mama tana da tumatur. A cikin zafi, tumatur yana laushi yana lalacewa da sauri.","en":"Mama has tomatoes. In the heat, tomatoes go soft and spoil fast."}},{"text":{"ha":"Wannan matsala ce. Za ka iya taimaka mata?","en":"This is a problem. Can you help her?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🔍","title":{"ha":"Matsala da mafita","en":"Problem and solution"},"lines":[{"text":{"ha":"Matsala ita ce abin da ke damun mutane.","en":"A problem is something that bothers people."}},{"text":{"ha":"Mafita ita ce abin da ke warware matsalar.","en":"A solution is something that fixes the problem."}},{"text":{"ha":"Tumatur yana lalacewa matsala ce. Na’urar sanyaya mafita ce.","en":"Spoiling tomatoes is a problem. A cooler is a solution."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"🏺","title":{"ha":"Sassan na’urar sanyaya","en":"The parts of the cooler"},"lines":[{"text":{"ha":"Tukwane biyu na yumɓu, ɗaya a cikin ɗaya.","en":"Two clay pots, one inside the other."}},{"text":{"ha":"Yashi mai ɗanshi a tsakanin su.","en":"Wet sand between them."}},{"text":{"ha":"Ruwa don jiƙa yashin.","en":"Water to wet the sand."}},{"text":{"ha":"Rigar da aka jiƙa a saman. Ana ajiye ta a inuwa.","en":"A damp cloth on top. Keep it in the shade."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"💨","title":{"ha":"Me ya sa abu mai ɗanshi yake sanyi?","en":"Why does a wet thing feel cool?"},"lines":[{"text":{"ha":"Idan rigar da ta jiƙe ta bushe a iska, hannunka yana jin sanyi.","en":"When a wet cloth dries in the wind, your arm feels cool."}},{"text":{"ha":"Na’urar sanyaya tana amfani da wannan abu: yashi mai ɗanshi yana bushewa, abinci kuma yana yin sanyi.","en":"The cooler uses the same idea: the wet sand dries and the food stays cool."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Manya ne kawai ke yanka, huda, amfani da wuta ko dafa ruwa.","en":"Only adults cut, drill, use fire or boil water."}},{"text":{"ha":"Yi amfani da ruwa mai tsabta. Kada ka yi amfani da kwalba da aka sa sinadari ko magani a ciki. Wannan wasa ne kawai.","en":"Use clean water. Never use a bottle that held chemicals or medicine. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"💰","title":{"ha":"Na’urar sanyaya tana da amfani","en":"A cooler is useful"},"lines":[{"text":{"ha":"Na’urar sanyaya tana taimaka wa iyali su adana abinci.","en":"A cooler helps a family keep food longer."}},{"text":{"ha":"Wani zai iya yin ta ya sayar. Za ka kalli yadda ake yi.","en":"Someone could make it and sell it. You will watch how it is made."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'cpots', 0, $j${"emoji":"🏺","name":{"ha":"Tara tukwane biyu","en":"Collect two clay pots"},"text":{"ha":"Ɗaya ƙarami, ɗaya babba, ƙarami ya shiga cikin babba.","en":"One small and one big. The small one fits inside the big one."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'csand', 1, $j${"emoji":"🏖️","name":{"ha":"Zuba yashi a ƙasa","en":"Put sand at the bottom"},"text":{"ha":"Ana zuba yashi a ƙasan babbar tukunya.","en":"Put a layer of sand at the bottom of the big pot."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'cinner', 2, $j${"emoji":"🫙","name":{"ha":"Saka ƙaramar tukunya","en":"Place the small pot inside"},"text":{"ha":"Ana saka ƙaramar tukunya a tsakiya.","en":"Place the small pot in the middle."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'cwet', 3, $j${"emoji":"💦","name":{"ha":"Cika gibin da yashi mai ɗanshi","en":"Fill the gap with wet sand"},"text":{"ha":"Ana zuba yashi da ruwa a gibin tsakanin tukwanen.","en":"Pour wet sand into the gap between the pots."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'cfood', 4, $j${"emoji":"🍅","name":{"ha":"Saka abinci","en":"Put food inside"},"text":{"ha":"Ana saka tumatur ko kayan marmari a ƙaramar tukunya.","en":"Put tomatoes or fruit into the small pot."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'ccover', 5, $j${"emoji":"🧺","name":{"ha":"Rufe da rigar da aka jiƙa","en":"Cover with a damp cloth"},"text":{"ha":"Ana rufe da rigar da aka jiƙa, a ajiye a inuwa.","en":"Cover with a damp cloth and keep it in the shade."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'cooler', 0, $j${"id":"cooler","emoji":"🏺","name":{"ha":"Tukwane biyu masu sanyaya abinci","en":"Pot-in-pot cooler"},"steps":["cpots","csand","cinner","cwet","cfood","ccover"],"summary":{"ha":"Sanyaya: yashi mai ɗanshi da rigar da aka jiƙa. Babu wuta, babu yanka.","en":"Cooling: wet sand and a damp cloth. No electricity and no cutting."},"result":{"emoji":"🏺","name":{"ha":"Na’urar sanyaya abinci","en":"A food cooler"}}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'sort', 0, $j${"type":"sort","key":"sort","items":[{"emoji":"🏺","kind":"yes","name":{"ha":"Tukunyar yumɓu","en":"Clay pot"},"why":{"ha":"Ita ce babban sashen na’urar.","en":"It is the main part of the cooler."}},{"emoji":"🏖️","kind":"yes","name":{"ha":"Yashi mai ɗanshi","en":"Wet sand"},"why":{"ha":"Yana tsakanin tukwanen kuma yana sanyaya.","en":"It sits between the pots and keeps things cool."}},{"emoji":"🧺","kind":"yes","name":{"ha":"Rigar da aka jiƙa","en":"Damp cloth"},"why":{"ha":"Tana rufe saman na’urar.","en":"It covers the top of the cooler."}},{"emoji":"🛍️","kind":"no","name":{"ha":"Leda","en":"Plastic bag"},"why":{"ha":"Ba a amfani da ita a wannan na’ura.","en":"It is not used in this cooler."}},{"emoji":"🔥","kind":"no","name":{"ha":"Gawayi mai zafi","en":"Hot charcoal"},"why":{"ha":"Gawayi mai zafi yana ƙonewa kuma ba ya sanyaya.","en":"Hot charcoal burns and does not cool."}},{"emoji":"🍬","kind":"no","name":{"ha":"Sukari","en":"Sugar"},"why":{"ha":"Sukari ba shi da aiki a na’urar sanyaya.","en":"Sugar has no job in a cooler."}}],"ask":{"ha":"Yana cikin na’urar sanyaya ko a’a?","en":"Does it go in the cooler?"},"options":[{"kind":"yes","icon":"✅","label":{"ha":"Eh, yana ciki","en":"Yes, it goes in"}},{"kind":"no","icon":"❌","label":{"ha":"A’a","en":"No"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'safety', 1, $j${"type":"safety","key":"safety","items":[{"emoji":"🍅","kind":"safe","name":{"ha":"Saka tumatur a ƙaramar tukunya","en":"Putting tomatoes in the small pot"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"💦","kind":"safe","name":{"ha":"Zuba ruwa mai tsabta a kan yashi","en":"Pouring clean water on the sand"},"why":{"ha":"Wannan lafiya ne, babba yana kusa.","en":"This is safe, with an adult nearby."}},{"emoji":"🔪","kind":"adult","name":{"ha":"Yanka ko huda tukunya","en":"Cutting or drilling a pot"},"why":{"ha":"Kayan huda suna da kaifi. Babba ne kawai.","en":"Drills and knives are sharp. Only an adult."}},{"emoji":"♨️","kind":"adult","name":{"ha":"Dafa ruwa ko amfani da wuta","en":"Boiling water or using fire"},"why":{"ha":"Zafi yana ƙonewa. Babba ne kawai.","en":"Heat burns. Only an adult."}},{"emoji":"🧪","kind":"adult","name":{"ha":"Amfani da tsohuwar kwalbar sinadari","en":"Using an old chemical bottle"},"why":{"ha":"Kada ka taɓa ta. Ka gaya wa babba.","en":"Do not touch it. Tell an adult."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'who', 2, $j${"type":"sort","key":"who","items":[{"emoji":"🍅","kind":"needs","name":{"ha":"Mai sayar da tumatur a kasuwa","en":"A tomato seller at the market"},"why":{"ha":"Tumatur ɗinsa yana lalacewa a rana.","en":"His tomatoes spoil in the sun."}},{"emoji":"🏠","kind":"needs","name":{"ha":"Iyali da ba su da firji","en":"A family with no fridge"},"why":{"ha":"Suna buƙatar hanyar adana abinci.","en":"They need a way to keep food."}},{"emoji":"🍊","kind":"needs","name":{"ha":"Manomi mai ’ya’yan itace","en":"A farmer with fruit to keep"},"why":{"ha":"’Ya’yan itace suna lalacewa idan ba a adana su ba.","en":"Fruit spoils if it is not kept well."}},{"emoji":"🧊","kind":"notneed","name":{"ha":"Wanda ke da firji da wuta","en":"Someone with a working fridge and electricity"},"why":{"ha":"Yana da wata hanyar sanyaya.","en":"They already have a way to keep food cool."}},{"emoji":"🍽️","kind":"notneed","name":{"ha":"Wanda ke ci abinci nan take","en":"Someone who eats the food at once"},"why":{"ha":"Abincin ba ya jira ya lalace.","en":"The food does not wait long enough to spoil."}}],"ask":{"ha":"Wa ke buƙatar na’urar sanyaya?","en":"Who needs a cooler?"},"options":[{"kind":"needs","icon":"✅","label":{"ha":"Yana buƙata","en":"Needs one"}},{"kind":"notneed","icon":"❌","label":{"ha":"Bai buƙata sosai","en":"Does not need one much"}}]}$j$::jsonb);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Daga ina mai ƙirƙira yake farawa?","en":"Where does an inventor start?"}$j$::jsonb, $j$[{"ha":"Daga matsala","en":"With a problem"},{"ha":"Daga na’ura mai tsada","en":"With an expensive machine"},{"ha":"Daga hutu","en":"With a rest"}]$j$::jsonb, 0, $j${"ha":"Mai ƙirƙira yana farawa da gano matsala.","en":"An inventor starts by finding a problem."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Me ke tsakanin tukwanen biyu?","en":"What goes between the two pots?"}$j$::jsonb, $j$[{"ha":"Yashi mai ɗanshi","en":"Wet sand"},{"ha":"Gawayi mai zafi","en":"Hot charcoal"},{"ha":"Sukari","en":"Sugar"}]$j$::jsonb, 0, $j${"ha":"Yashi mai ɗanshi yana tsakanin tukwanen.","en":"Wet sand goes between the pots."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Me ake sa a saman na’urar?","en":"What goes on top of the cooler?"}$j$::jsonb, $j$[{"ha":"Rigar da aka jiƙa","en":"A damp cloth"},{"ha":"Dutse mai zafi","en":"A hot stone"},{"ha":"Leda","en":"A plastic bag"}]$j$::jsonb, 0, $j${"ha":"Ana rufe na’urar da rigar da aka jiƙa.","en":"The cooler is covered with a damp cloth."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Wa ke huda ko yanka tukunya?","en":"Who cuts or drills a pot?"}$j$::jsonb, $j$[{"ha":"Babba","en":"An adult"},{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Kowa","en":"Anyone"}]$j$::jsonb, 0, $j${"ha":"Kayan huda suna da kaifi. Babba ne kawai.","en":"Drills and knives are sharp. Only an adult."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Wane ne mafita ga tumatur da ke lalacewa?","en":"Which is a solution to spoiling tomatoes?"}$j$::jsonb, $j$[{"ha":"Na’urar sanyaya","en":"A cooler"},{"ha":"Barin su a rana","en":"Leaving them in the sun"},{"ha":"Jefar da su","en":"Throwing them away"}]$j$::jsonb, 0, $j${"ha":"Mafita tana warware matsala. Na’urar sanyaya tana taimakawa.","en":"A solution fixes a problem. A cooler helps."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"A ina ya kamata a ajiye na’urar sanyaya?","en":"Where should the cooler stand?"}$j$::jsonb, $j$[{"ha":"A inuwa","en":"In the shade"},{"ha":"A cikin rana mai zafi","en":"In the hot sun"},{"ha":"Kusa da wuta","en":"Near a fire"}]$j$::jsonb, 0, $j${"ha":"Inuwa tana taimaka wa na’urar ta yi sanyi.","en":"Shade helps the cooler stay cool."}$j$::jsonb, 5);
  insert into public.missions (slug, mission_no, emoji, title, description, category_id, difficulty, status, stages, reward_rules, engine_options, objectives, access, level_id, risk_level, family)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"🧑🏾‍🔬","title":{"ha":"Aikin ƙirƙira","en":"The design brief"},"lines":[{"text":{"ha":"Aikinka: ƙirƙiri mafita mai sauƙin kuɗi da za ta taimaka wa gidaje su rage ɓarnar abinci ko su adana abinci.","en":"Your brief: design a low-cost solution that helps households reduce food waste or improve food storage."}},{"text":{"ha":"Za ka yi aiki kamar ƙwararren mai ƙirƙira: bincike, tsari, gwaji, lissafi, da gabatarwa.","en":"You will work like a real designer: research, plan, test, calculate and present."}},{"text":{"ha":"Na’urar sanyaya ta tukwane biyu misali ne, ba amsa ba. Ƙirƙiri naka.","en":"The pot-in-pot cooler is an example, not the answer. Design your own."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🔄","title":{"ha":"Tunanin mai ƙirƙira","en":"Design thinking"},"lines":[{"text":{"ha":"Gano matsala → Bincika masu amfani → Tsara → Gina tare da babba → Gwada → Gyara → Gabatar","en":"Find the problem → Research users → Plan → Build with an adult → Test → Improve → Present"}},{"text":{"ha":"Na farko ba ya zama cikakke. Kuskure yana nuna mana abin da za mu gyara.","en":"The first design is rarely perfect. Mistakes show us what to improve."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"🗣️","title":{"ha":"Ka fahimci matsalar da mai amfani","en":"Understand the problem and the user"},"lines":[{"text":{"ha":"Tambayi aƙalla mutum uku yadda abinci yake lalacewa a gidansu ko a wurin sayarwarsu.","en":"Ask at least three people how food spoils in their home or stall."}},{"text":{"ha":"Tambayoyi: Wane abinci ke lalacewa? Cikin kwanaki nawa? Me suke yi yanzu? Nawa suke asara?","en":"Ask: Which food spoils? How fast? What do they do now? How much do they lose?"}},{"text":{"ha":"Rubuta abin da suka faɗa, ba abin da kake tsammani ba.","en":"Write what people say, not what you expect."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"🧱","title":{"ha":"Kayan aiki da halayensu","en":"Materials and their properties"},"lines":[{"text":{"ha":"Yumɓu yana da ƙananan ramuka, don haka ruwa yana iya ratsawa ta cikinsa. Filastik ba ya barin ruwa ya ratsa.","en":"Clay has tiny pores, so water can pass through it. Plastic does not let water through."}},{"text":{"ha":"Ka kwatanta kayan: farashi, samuwa a yankinka, ƙarfi, da iyakokinsu.","en":"Compare materials: cost, availability near you, strength and limits."}},{"text":{"ha":"Yumɓu na iya fashewa idan ya faɗi. Ka yi tunanin madadi, misali tukunyar da aka riga aka yi amfani da ita.","en":"Clay can crack if dropped. Think of alternatives, such as a second-hand pot."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"🔬","title":{"ha":"Kimiyya a bayan sa","en":"The science behind it"},"lines":[{"text":{"ha":"Idan ruwa yana ƙafewa, yana buƙatar kuzari. Yana ɗaukar wannan kuzari ne daga zafin abin da ke kewaye da shi, don haka kewayen yana yin sanyi.","en":"When water evaporates it needs energy. It takes that energy as heat from its surroundings, so the surroundings get cooler."}},{"text":{"ha":"Zafi, bushewar iska da iska mai motsi suna sa ƙafewa ya yi sauri. Iska mai ɗanshi tana rage shi.","en":"Heat, dry air and moving air make evaporation faster. Humid air slows it down."}},{"text":{"ha":"Don haka na’urar tana aiki mafi kyau a yanayi mai zafi da bushewa.","en":"So this kind of cooler works best in hot, dry weather."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"📋","title":{"ha":"Shirya gwaji mai adalci","en":"Plan a fair test"},"lines":[{"text":{"ha":"Canza abu ɗaya kawai a lokaci guda, misali yashi mai ɗanshi da yashi busasshe.","en":"Change one thing at a time, for example wet sand against dry sand."}},{"text":{"ha":"Ka ajiye sauran abubuwa iri ɗaya: tukunya, wuri, da lokaci.","en":"Keep everything else the same: pot, place and time."}},{"text":{"ha":"Ka ɗauki karatu fiye da ɗaya, ka rubuta su a tebur.","en":"Take more than one reading and write them in a table."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"🧮","title":{"ha":"Lissafin sakamako","en":"Calculate the results"},"lines":[{"text":{"ha":"Bambancin zafi (ΔT) = zafin waje − zafin ciki.","en":"Temperature difference (ΔT) = outside temperature − inside temperature."}},{"text":{"ha":"Matsakaici = jimillar karatu ÷ adadin karatu.","en":"Average = total of the readings ÷ number of readings."}},{"text":{"ha":"Misali (lambobin misali ne): waje 34, 35, 33 → matsakaici 34. Ciki 24, 25, 23 → matsakaici 24. ΔT = 10 °C.","en":"Example (example numbers): outside 34, 35, 33 → average 34. Inside 24, 25, 23 → average 24. ΔT = 10 °C."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 7, $j${"emoji":"💰","title":{"ha":"Kuɗi da ƙima","en":"Cost and value"},"lines":[{"text":{"ha":"Akwai kuɗin da ake kashewa sau ɗaya (misali kayan aiki) da kuɗin kayan kowace na’ura (kuɗin raka’a).","en":"There is a one-off cost (for example tools) and the material cost of each unit (unit cost)."}},{"text":{"ha":"Kuɗin shiga = farashi × adadin da aka sayar. Riba = kuɗin shiga − jimillar kuɗin da aka kashe.","en":"Revenue = price × units sold. Profit = revenue − total cost."}},{"text":{"ha":"Matakin daidaito (break-even) = kuɗin sau ɗaya ÷ (farashi − kuɗin raka’a).","en":"Break-even = one-off cost ÷ (price − unit cost)."}},{"text":{"ha":"Lambobin da ke wannan darasi misali ne kawai. Yi amfani da farashin kasuwar yankinka.","en":"The numbers in this lesson are examples only. Use prices from your local market."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 8, $j${"emoji":"✅","title":{"ha":"Kula da inganci","en":"Quality control"},"lines":[{"text":{"ha":"Ka tabbatar kowace na’ura iri ɗaya ce: girman tukunya, yawan yashi, babu tsaga.","en":"Make every unit the same: pot size, amount of sand, no cracks."}},{"text":{"ha":"Ka rubuta yadda za ka bincika kowace na’ura kafin ka ba mai saye.","en":"Write how you will check each unit before giving it to a customer."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 9, $j${"emoji":"🌍","title":{"ha":"Muhalli da gaskiya","en":"Environment and honesty"},"lines":[{"text":{"ha":"Ba ta buƙatar wutar lantarki, kuma tana amfani da kayan da ake da su a yankin.","en":"It needs no electricity and uses local materials."}},{"text":{"ha":"Kada ka ce na’urarka tana yin abin da ba ka gwada ba, misali warkar da cuta.","en":"Never claim your device does something you did not test, such as curing sickness."}},{"text":{"ha":"Ruwa mai tsayuwa na iya jawo sauro. Ka rufe shi ko ka zubar.","en":"Standing water can attract mosquitoes. Cover it or empty it."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 10, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Manya ne kawai ke yanka, huda, amfani da wuta ko dafa ruwa.","en":"Only adults cut, drill, use fire or boil water."}},{"text":{"ha":"Kada ka yi amfani da kwalba ko jarka da aka sa sinadari, mai ko magani a ciki. Wannan wasa ne kawai.","en":"Never use a bottle or jerrycan that held chemicals, fuel or medicine. This is a game only."}},{"text":{"ha":"Kada ka ajiye nama ko dafaffen abinci a wannan na’ura. Na kayan lambu da ’ya’yan itace ne.","en":"Do not store raw meat or cooked food in this cooler. It is for vegetables and fruit."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 11, $j${"emoji":"🎤","title":{"ha":"Gabatar da ra’ayinka","en":"Present your idea"},"lines":[{"text":{"ha":"Ka bayyana matsalar, mafitarka, kayan da ka yi amfani da su, yadda take aiki, abin da ka koya, da abin da za ka gyara.","en":"Explain the problem, your solution, the materials, how it works, what you learned and what you would improve."}},{"text":{"ha":"Ka kare shawarwarinka da shaida daga gwajinka.","en":"Defend your choices with evidence from your own test."}},{"text":{"ha":"Ka gabatar a gaban ajinka ko iyalinka.","en":"Present to your class or your family."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'j1', 0, $j${"emoji":"🔍","name":{"ha":"Gano matsala","en":"Identify the problem"},"text":{"ha":"Ka bayyana matsalar da wanda yake fama da ita.","en":"State the problem and who has it."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'j2', 1, $j${"emoji":"🗣️","name":{"ha":"Tambayi masu amfani","en":"Interview users"},"text":{"ha":"Ka tambayi aƙalla mutum uku, ka rubuta amsoshinsu.","en":"Ask at least three people and write down their answers."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'j3', 2, $j${"emoji":"🧱","name":{"ha":"Zaɓi kayan aiki","en":"Choose materials"},"text":{"ha":"Ka kwatanta kayan da ake da su, ka zaɓi mafi dacewa.","en":"Compare the available materials and choose the most suitable."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'j4', 3, $j${"emoji":"🔬","name":{"ha":"Bayyana kimiyya","en":"Explain the science"},"text":{"ha":"Ka bayyana dalilin da ya sa mafitarka za ta yi aiki.","en":"Explain why your solution should work."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'j5', 4, $j${"emoji":"✏️","name":{"ha":"Zana tsari","en":"Sketch the plan"},"text":{"ha":"Ka zana na’urar, ka rubuta sassanta da abin da za ka auna.","en":"Draw the device, label the parts and say what you will measure."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'j6', 5, $j${"emoji":"🔨","name":{"ha":"Gina tare da babba","en":"Build with an adult"},"text":{"ha":"Babba yana yin yanka da huda; kai kana taimakawa a sauran.","en":"An adult does any cutting and drilling; you help with the rest."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'j7', 6, $j${"emoji":"🧪","name":{"ha":"Gwada ka rubuta","en":"Test and record"},"text":{"ha":"Ka canza abu ɗaya kawai, ka ɗauki karatu fiye da ɗaya.","en":"Change one thing only and take more than one reading."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'j8', 7, $j${"emoji":"🧮","name":{"ha":"Lissafa","en":"Calculate"},"text":{"ha":"Ka nemo matsakaici da bambancin zafi.","en":"Work out the averages and the temperature difference."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'j9', 8, $j${"emoji":"💰","name":{"ha":"Lissafa kuɗi da farashi","en":"Work out cost and price"},"text":{"ha":"Ka nemo kuɗin raka’a, farashi, riba da matakin daidaito.","en":"Work out unit cost, price, profit and break-even."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'j10', 9, $j${"emoji":"🔧","name":{"ha":"Gyara","en":"Improve"},"text":{"ha":"Ka nemo rauni, ka gyara, ka kwatanta na farko da na yanzu.","en":"Find the weak points, improve, and compare the first and improved designs."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'j11', 10, $j${"emoji":"🎤","name":{"ha":"Gabatar","en":"Present"},"text":{"ha":"Ka bayyana matsala, mafita, abin da ka koya, da abin da za ka gyara.","en":"Explain the problem, solution, what you learned and what you would change."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'journey', 0, $j${"id":"journey","emoji":"🧭","name":{"ha":"Hanyar mai ƙirƙira","en":"The designer’s journey"},"steps":["j1","j2","j3","j4","j5","j6","j7","j8","j9","j10","j11"],"summary":{"ha":"Daga matsala zuwa mafita da aka gwada: bincike, tsari, gwaji, lissafi, gyara, gabatarwa.","en":"From problem to tested solution: research, plan, test, calculate, improve, present."},"result":{"emoji":"💡","name":{"ha":"Mafita da aka gwada","en":"A tested solution"}}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'claims', 0, $j${"type":"sort","key":"claims","items":[{"emoji":"🌡️","kind":"evidence","name":{"ha":"Na’urarmu ta yi sanyi da 10 °C fiye da waje a karatu uku.","en":"Our cooler was 10 °C cooler than outside in three readings."},"why":{"ha":"Akwai karatu da aka auna.","en":"There are measured readings to support it."}},{"emoji":"🩺","kind":"claim","name":{"ha":"Wannan na’urar za ta warkar da cuta.","en":"This cooler will cure sickness."},"why":{"ha":"Ba a gwada ba, kuma ba a iya faɗa ba tare da shaida ba.","en":"It was not tested, and cannot be said without evidence."}},{"emoji":"🔌","kind":"evidence","name":{"ha":"Na’urar ba ta amfani da wutar lantarki.","en":"The cooler uses no electricity."},"why":{"ha":"Wannan gaskiya ce game da yadda aka tsara ta.","en":"This is a fact about how it is designed."}},{"emoji":"🛒","kind":"claim","name":{"ha":"Kowa zai saya.","en":"Everyone will buy it."},"why":{"ha":"Ba a tambayi masu saye ba tukuna.","en":"No customers have been asked yet."}}],"ask":{"ha":"Shaida ce ko da’awa da ba a tabbatar ba?","en":"Is it backed by evidence, or not proven yet?"},"options":[{"kind":"evidence","icon":"📊","label":{"ha":"Akwai shaida","en":"Backed by evidence"}},{"kind":"claim","icon":"❓","label":{"ha":"Ba a tabbatar ba","en":"Not proven yet"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'safety', 1, $j${"type":"safety","key":"safety","items":[{"emoji":"🗣️","kind":"safe","name":{"ha":"Tambayar masu amfani da rubuta amsa","en":"Interviewing users and writing answers"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"🌡️","kind":"safe","name":{"ha":"Karanta ma’aunin zafi da rubutawa","en":"Reading a thermometer and recording it"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"🔪","kind":"adult","name":{"ha":"Yanka ko huda tukunya ko jarka","en":"Cutting or drilling a pot or jerrycan"},"why":{"ha":"Kayan huda suna da kaifi. Babba ne kawai.","en":"Drills and knives are sharp. Only an adult."}},{"emoji":"♨️","kind":"adult","name":{"ha":"Dafa ruwa ko amfani da wuta","en":"Boiling water or using fire"},"why":{"ha":"Zafi yana ƙonewa. Babba ne kawai.","en":"Heat burns. Only an adult."}},{"emoji":"🧪","kind":"adult","name":{"ha":"Amfani da sinadari don tsabtace na’urar","en":"Using chemicals to clean the device"},"why":{"ha":"Kada ka taɓa sinadari. Ka gaya wa babba.","en":"Do not touch chemicals. Tell an adult."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'challenge', 'business', 2, $j${"type":"business","key":"business"}$j$::jsonb);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Ka kwatanta yashi mai ɗanshi da busasshe a tukwane iri ɗaya, a inuwa ɗaya. Wane abu ne kake canzawa?","en":"You compare wet sand with dry sand in identical pots in the same shade. What is the one thing you change?"}$j$::jsonb, $j$[{"ha":"Ko yashin yana da ɗanshi","en":"Whether the sand is wet"},{"ha":"Girman tukunya","en":"The size of the pot"},{"ha":"Wurin da aka ajiye","en":"The place"}]$j$::jsonb, 0, $j${"ha":"A gwaji mai adalci ana canza abu ɗaya kawai.","en":"In a fair test you change only one thing."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Zafin waje 34 °C, zafin ciki 24 °C. Menene ΔT?","en":"Outside 34 °C, inside 24 °C. What is ΔT?"}$j$::jsonb, $j$[{"ha":"10 °C","en":"10 °C"},{"ha":"58 °C","en":"58 °C"},{"ha":"24 °C","en":"24 °C"}]$j$::jsonb, 0, $j${"ha":"ΔT = 34 − 24 = 10 °C.","en":"ΔT = 34 − 24 = 10 °C."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Tukwane biyu suna kan ₦900, yashi da rigar kuma ₦100. Menene kuɗin raka’a?","en":"Two pots cost ₦900 and the sand and cloth cost ₦100. What is the unit cost?"}$j$::jsonb, $j$[{"ha":"₦1,000","en":"₦1,000"},{"ha":"₦900","en":"₦900"},{"ha":"₦100","en":"₦100"}]$j$::jsonb, 0, $j${"ha":"900 + 100 = ₦1,000 ga kowace na’ura.","en":"900 + 100 = ₦1,000 per unit."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Farashin sayarwa ₦1,800, kuɗin raka’a ₦1,000, ka sayar da guda 10. Babu wani kuɗi. Menene riba?","en":"Selling price ₦1,800, unit cost ₦1,000, you sell 10. There is no other cost. What is the profit?"}$j$::jsonb, $j$[{"ha":"₦8,000","en":"₦8,000"},{"ha":"₦18,000","en":"₦18,000"},{"ha":"₦800","en":"₦800"}]$j$::jsonb, 0, $j${"ha":"Kuɗin shiga 18,000 − kuɗin da aka kashe 10,000 = ₦8,000.","en":"Revenue 18,000 − cost 10,000 = ₦8,000."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Kuɗin sau ɗaya ₦2,000, farashi ₦1,800, kuɗin raka’a ₦1,000. Guda nawa ake sayarwa kafin a rufe kuɗin?","en":"One-off cost ₦2,000, price ₦1,800, unit cost ₦1,000. How many units must you sell to cover the cost?"}$j$::jsonb, $j$[{"ha":"3","en":"3"},{"ha":"2","en":"2"},{"ha":"10","en":"10"}]$j$::jsonb, 0, $j${"ha":"2,000 ÷ (1,800 − 1,000) = 2.5, don haka guda 3.","en":"2,000 ÷ (1,800 − 1,000) = 2.5, so 3 units."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Wane ne da’awa mai rauni?","en":"Which is a weak claim?"}$j$::jsonb, $j$[{"ha":"Wannan na’urar tana sa abinci ya zama lafiya har abada.","en":"This cooler makes food safe forever."},{"ha":"Na auna zafin ciki sau uku.","en":"I measured the inside temperature three times."},{"ha":"Ba ta amfani da wutar lantarki.","en":"It uses no electricity."}]$j$::jsonb, 0, $j${"ha":"Ba a gwada “har abada” ba, don haka da’awa ce mara shaida.","en":"“Forever” was never tested, so it is a claim with no evidence."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"A rana mai ɗanshi na’urar ba ta yi sanyi sosai ba. Wane gyara ne mai ma’ana a gwada na gaba?","en":"On a humid day the cooler was not very cool. Which is a sensible improvement to test next?"}$j$::jsonb, $j$[{"ha":"A ajiye ta a inuwa inda iska ke motsi, a sake gwadawa","en":"Keep it in the shade where air moves, then test again"},{"ha":"A cire yashin","en":"Remove the sand"},{"ha":"A daina gwaji","en":"Stop testing"}]$j$::jsonb, 0, $j${"ha":"Iska mai motsi tana taimaka wa ƙafewa. Ka gwada, ka auna.","en":"Moving air helps evaporation. Test it and measure."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 7, $j${"ha":"Wane ne binciken inganci mai kyau?","en":"Which is a good quality check?"}$j$::jsonb, $j$[{"ha":"A duba kowace tukunya don tsaga, a yi amfani da yashi iri ɗaya","en":"Check each pot for cracks and use the same amount of sand"},{"ha":"A yi wa kowace tukunya fenti ja","en":"Paint every pot red"},{"ha":"A sayar da duka da sauri","en":"Sell them all quickly"}]$j$::jsonb, 0, $j${"ha":"Inganci yana nufin kowace na’ura ta yi daidai.","en":"Quality means every unit performs the same."}$j$::jsonb, 5);
